import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

def transform(grid):
    H=len(grid); W=len(grid[0])
    out=[row[:] for row in grid]
    marks=[(i,j) for i in range(H) for j in range(W) if grid[i][j]==3]
    for r,c in marks:
        for dj in range(-2,3): 
            if 0<=r-2<H and 0<=c+dj<W: out[r-2][c+dj]=5
        for rr,pat in ((r-1,{(-2):2,0:5,2:2}),(r,{-2:2,0:3,2:2}),(r+1,{-2:2,2:2})):
            if 0<=rr<H:
                for dj,v in pat.items():
                    if 0<=c+dj<W: out[rr][c+dj]=v
        if 0<=r+2<H:
            for dj in range(-2,3):
                if 0<=c+dj<W: out[r+2][c+dj]=8
            for j in range(W):
                if out[r+2][j]==0: out[r+2][j]=2
    return out

pred=transform(G['Demo pair 1 input'])
print(pred==G['Demo pair 1 output'])
if pred!=G['Demo pair 1 output']:
    for a,b in zip(pred,G['Demo pair 1 output']):
        print(a); print(b); print()

